// Helpers for list views.
export function truncate(text, max) {
  if (text.length <= max) return text;
  if (max < 3) return text.slice(0, Math.max(0, max));
  return text.slice(0, max - 3) + '...';
}

export function capitalize(text) {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { truncate, capitalize } from '../src/text.js';

test('short text is left alone', () => assert.equal(truncate('hi', 5), 'hi'));
test('capitalize raises the first letter', () => assert.equal(capitalize('ab'), 'Ab'));

test('text already at max length is unchanged', () => {
  assert.equal(truncate('hello', 5), 'hello');
});

test('cut text ends in ... and fits within max', () => {
  assert.equal(truncate('hello world', 8), 'hello...');
  assert.equal(truncate('hello world', 8).length, 8);
});

test('the ellipsis counts inside max', () => {
  assert.equal(truncate('abcdef', 3), '...');
  assert.equal(truncate('abcdef', 4), 'a...');
});

test('a very small max is respected without exceeding it', () => {
  assert.equal(truncate('hello', 0), '');
  assert.equal(truncate('hello', 1), 'h');
  assert.equal(truncate('hello', 2), 'he');
});

test('result never exceeds max', () => {
  const text = 'abcdefghijklmnopqrstuvwxyz';
  for (let max = 0; max <= text.length + 2; max += 1) {
    assert.ok(truncate(text, max).length <= max, `max=${max} produced too long a result`);
  }
});

